#pragma once

// Pure checks for bounded, replay-safe staging. Not an authentication layer.
#include "config_v2_generation_selection.hpp"
#include <cstddef>
#include <cstdint>
#include <string_view>

namespace config_v2_stage_policy {

constexpr std::size_t kMaxChunkBytes = 1024;
constexpr uint64_t kMaxStagedFileBytes = 256u * 1024u;
constexpr uint64_t kMinFreeReserveBytes = 128u * 1024u;

inline bool transactionIdValid(std::string_view id) {
  // Random 128-bit ID, hex encoded; generated by the device, never by client.
  if (id.size() != 32)
    return false;
  for (char c : id)
    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')))
      return false;
  return true;
}

enum class ChunkDecision { Append, RetryCompare, Reject };

inline ChunkDecision classifyChunk(uint64_t written, uint64_t offset,
                                   std::size_t count, uint64_t total) {
  if (count == 0 || count > kMaxChunkBytes || total == 0 ||
      total > kMaxStagedFileBytes || written > total || offset > written ||
      count > total - offset)
    return ChunkDecision::Reject;
  if (offset == written)
    return ChunkDecision::Append;
  if (count <= written - offset)
    return ChunkDecision::RetryCompare;
  return ChunkDecision::Reject; // Overlapping partial append is not idempotent.
}

// Must reserve flash for both confirmed generations AND staged data. This is
// only an initial conservative space estimate, not a filesystem guarantee.
inline bool hasCapacity(uint64_t total, uint64_t used,
                        uint64_t requiredNewBytes) {
  if (used > total || requiredNewBytes > total - used)
    return false;
  return total - used - requiredNewBytes >= kMinFreeReserveBytes;
}

} // namespace config_v2_stage_policy
